22:    /** The nights of a stay summed up, with a percentage discount taken off the sum. */
23:    Price nightlyPrice(Room room, LocalDate checkIn, LocalDate checkOut, BigDecimal discountRate) {
24:        int nights = 0;
25:        BigDecimal subtotal = cents(BigDecimal.ZERO);
26:        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
27:            subtotal = subtotal.add(nightPrice(room, night));
28:            nights++;
29:        }
30:        BigDecimal discount = cents(subtotal.multiply(discountRate));
31:        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
32:    }
